	private static List<String> drainParallel(TrackingSource source, IRI edge, Throwable failure,
			Throwable forkCleanup, boolean failAtFork, AtomicInteger filterCloses) throws IOException {
		long predicate = source.idOf(edge);
		assertThat(predicate).isNotEqualTo(NativeLmdbQuerySource.UNKNOWN_ID);
		PatternPlan[] patterns = new PatternPlan[] {
				new PatternPlan(Term.slot(0), Term.constant(predicate), Term.slot(1), Term.unbound(),
						ContextConstraint.UNRESTRICTED, false, 6D),
				new PatternPlan(Term.slot(1), Term.constant(predicate), Term.slot(2), Term.unbound(),
						ContextConstraint.UNRESTRICTED, false, 6D),
				new PatternPlan(Term.slot(2), Term.constant(predicate), Term.slot(0), Term.unbound(),
						ContextConstraint.UNRESTRICTED, false, 6D) };
		AtomicInteger forks = new AtomicInteger();
		NativeBooleanFilter filter = new NativeBooleanFilter() {
			@Override
			public boolean accept(RowState row) {
				return true;
			}

			@Override
			public NativeBooleanFilter forkForParallelWorker() {
				if (forks.incrementAndGet() == 2 && failAtFork) {
					raise(failure);
				}
				return new NativeBooleanFilter() {
					@Override
					public boolean accept(RowState row) {
						return true;
					}

					@Override
					public void close() {
						filterCloses.incrementAndGet();
						Throwable problem = failAtFork ? forkCleanup : failure;
						if (problem != null) {
							raise(problem);
						}
					}
				};
			}
		};
		var plan = new LmdbNativeLeapfrogJoin.LeapfrogPlan(patterns,
				new MaskedFilter[] { new MaskedFilter(filter, 7L) });
		var layout = new NativeSlotLayout(Map.of("x", 0, "y", 1, "z", 2), null);
		layout.freeze(List.of("x", "y", "z"));
		RowState row = new RowState(source, layout, EmptyBindingSet.getInstance());
		assertThat(LmdbNativeAggregateCompiler.initializeRow(row, EmptyBindingSet.getInstance(), source, layout))
				.as("the ordinary native entry must seed UNKNOWN slots before a cursor opens")
				.isTrue();
		long before = LmdbNativeLeapfrogJoin.PARALLEL_RUNS.get();
		List<String> rows = new ArrayList<>();
		try (RowCursor cursor = plan.open(row)) {
			try {
				while (cursor.next()) {
					rows.add(node(source.lazyValue(row.slots[0])) + "/" + node(source.lazyValue(row.slots[1]))
							+ "/" + node(source.lazyValue(row.slots[2])));
				}
			} finally {
				if (!failAtFork) {
					assertThat(LmdbNativeLeapfrogJoin.PARALLEL_RUNS.get()).as("real parallel owner must engage")
							.isGreaterThan(before);
				}
				assertThat(forks).as("two real worker fork requests reached setup").hasValue(2);
			}
		}
		return rows;
	}

	private static void raise(Throwable failure) {
		if (failure instanceof Error error) {
			throw error;
		}
		throw (RuntimeException) failure;
	}

	private static String node(Value value) {
		String text = value.stringValue();
		assertThat(text).startsWith("urn:parallel-cleanup:n");
		return text.substring("urn:parallel-cleanup:n".length());
	}

	private static void restore(String key, String value) {
		if (value == null) {
			System.clearProperty(key);
		} else {
			System.setProperty(key, value);
		}
	}

	/** Physical lifetime decorator over real LMDB siblings; never used as qualified learning source identity. */
